import sailpoint.object.TaskDefinition;
import sailpoint.object.TaskResult;
import sailpoint.object.Application;
import sailpoint.object.Link;
import sailpoint.object.Identity;
import java.util.*;

String taskName="Sky-Find-accountOwner";
TaskDefinition taskDef=context.getObjectByName(TaskDefinition.class,taskName);
TaskResult taskRes=context.getObjectByName(TaskResult.class,taskName);

// retriving data from the taskDefination
String appName=taskDef.getString("appName");
String accountName=taskDef.getString("accountDisplayName");

if(taskName!=null && taskDef!=null)
{
	if(true)
  {
  	taskRes.setAttribute("info","Please find the below Owner details for the requested account");
    taskRes.setAttribute("Owner","Aloke");
    context.saveObject(taskRes);
    context.commitTransaction();
  }
  else
  {

  }
}

log.error("Task Rule executed successfully ......................");
